        lookup, "concat", methodType(String::class.java, Int::class.javaPrimitiveType, Long::class.javaPrimitiveType),
        "row \u0001 has \u0001 seats",
    )
    println("${concat.target.invoke(12, 30L)}  <- call site: ${concat.javaClass.simpleName}")
}

